  day: [["6:00 AM", "Shift handoff: review SCADA trends, chemical levels and overnight alarms."], ["6:30 AM", "Walk the plant: check pumps, chemical feeders and filter performance."], ["8:00 AM", "Collect samples and test chlorine residual, turbidity and pH in the plant lab."], ["10:00 AM", "Backwash a filter after headloss reaches its setpoint."], ["12:00 PM", "Adjust the coagulant dose after a storm raises raw-water turbidity."], ["2:00 PM", "Perform preventive maintenance on a chemical metering pump and log readings for the monthly report."]],
